// Monta o texto da mensagem de acordo com o "tipo" do evento -- ver os 4 tipos que o Mapa
// da Proteção dispara em src/app/captacao/actions.ts (comentário 01-gerar-texto-PROMPT.md
// não se aplica aqui, é só referência de onde os campos vêm).
const d = $input.first().json.body;

const mensagens = {
  lead_novo: `🆕 Lead novo: ${d.nome}${d.profissao ? ` (${d.profissao})` : ''} — via ${d.origem || 'link de captação'}.`,
  lead_repetido: `🔁 ${d.nome} preencheu o link de novo (lead repetido) — via ${d.origem || 'link de captação'}.`,
  pediu_whatsapp: `💬 ${d.nome} pediu pra ser chamado no WhatsApp em vez de agendar um horário.`,
  horario_escolhido: `📅 ${d.nome} escolheu um horário de reunião — confira a agenda.`,
};

let mensagem = mensagens[d.tipo] || `Mapa da Proteção: evento "${d.tipo}" de ${d.nome}.`;

// Contato do lead junto, pra responder na hora sem precisar abrir o painel primeiro (pedido
// real do Edgar, 2026-09-07). Só entra a linha se tiver telefone ou e-mail.
const contato = [d.telefone ? `📞 ${d.telefone}` : null, d.email ? `✉️ ${d.email}` : null].filter(Boolean).join(' · ');
if (contato) mensagem += `\n${contato}`;

// corretorWhatsapp chega formatado, tipo "(96) 98888-7777" -- a Evolution API espera só dígitos
// com código do país, tipo "5596988887777". Mesma lógica de linkWhatsapp() em
// src/lib/formato.ts, portada aqui pro n8n.
const digitos = (d.corretorWhatsapp || '').replace(/\D/g, '');
const numero = digitos.length === 11 ? `55${digitos}` : digitos;

return [{ json: { mensagem, numero } }];
